      backup_text =
        "type Operation = (name=String, requires=[(enforced=Bool, String)], \
         ensures=[(enforced=Bool, String)],  operation=  , notes=[String]) in\n\n\
         let operations : [Operation] = [\n\
         (\n\
         name=\"flatten\", \n\
         requires=[\n\
         (enforced=false, \"cs has no duplicates\"),\n\
         (enforced=false, \"for all c in cs, c is in header(t1)\"),\n\
         (enforced=false, \"for all c in cs, schema(t1)[c] is Seq<X> for some \
         sort X\"),\n\
         (enforced=false, \"for all i in range(nrows(t1)), for all c1 and c2 \
         in cs, length(getValue(getRow(t1, i), c1)) is equal to \
         length(getValue(getRow(t1, i), c2))\")\n\
         ], \n\
         ensures=[\n\
         (enforced=false, \"header(t2) is equal to header(t1)\"),\n\
         (enforced=false, \"for all c in header(t2) :\"\n\
         ++ \"if c is in cs then schema(t2)[c] is equal to the element sort of \
         schema(t1)[c]\"\n\
         ++ \"otherwise, schema(t2)[c] is equal to schema(t1)[c]\")\n\
         ], \n\
         operation=let flatten =fun (t1 :[?],cs:[String]) ->\n\
         let select_cols =fun (r:?,cs:[String]) ->\n\
         to_lvs(r) |>(fun entries ->filter_map(cs,fun c -> \
         find_opt(entries,fun e ->e.label ==c))) |>from_lvs \n\
         in                          \n\
         flat_map(t1,fun r ->\n\
         let (non_seq_entries,seq_entries)=\n\
         partition(to_lvs(r),fun (label=l,value=v) -> !mem(cs,l)) in\n\n\
         case map(seq_entries,fun (label=l,value=vs) -> map(vs,fun v \
         ->[(label=l,value=v)]))\n\
         |[] =>[]\n\
         |(col1 ::cols) =>\n\
         fold_left(cols,\n\
         fun (acc,a) -> zip(acc,a) |>map(_,fun (a,b) ->a @b),\n\
         col1) |> map(_,from_lvs) \n\
         end |> map(_,fun rest ->r ...rest)\n\
         ) \n\
         in,\n\
         notes=[\"The idiomatic way to do this would be to do an ordinary \
         flat_map and project out the columns with an internal map\"]\n\
         ),\n\
         (\n\
         name=\"transformColumn\",\n\
         requires=[(enforced=false, \"c is in header(t1) \")],\n\
         ensures=[\n\
         (enforced=false, \"v1 is of sort schema(t1)[c]\"),\n\
         (enforced=false, \"header(t2) is equal to header(t1)\"),\n\
         (enforced=false, \"for all c' in header(t2),\"),\n\
         (enforced=false, \"for all c' in header(t2), if c' is equal to c then \
         schema(t2)[c'] is equal to the sort of v2\"),\n\
         (enforced=false, \"otherwise, then schema(t2)[c'] is equal to \
         schema(t1)[c']\"),\n\
         (enforced=false, \"nrows(t2) is equal to nrows(t1)\")\n\
         ],\n\
         operation=let transform_column =\n\
         fun (t:[?],c:String,f :(? ->?)) ->\n\
         map(t,fun r ->map(to_lvs(r), fun e -> if e.label ==c then \
         (label=e.label,value=f(e.value)) else e) |> from_lvs) \n\
         in,\n\
         notes=[\"The idiomatic way would be to do a map and use tuple \
         extension to transform the column\"]\n\
         ),\n\
         (\n\
         name=\"renameColumns\",\n\
         requires=[\n\
         (enforced=false, \"for all (c1, _) in ccs, c1 is in header(t1)\"),\n\
         (enforced=false, \"[c1 | (c1, _) in ccs] has no duplicates\"),\n\
         (enforced=false, \"concat(removeAll(header(t1), [c1 | (c1, _) in \
         ccs]), [c2 | (_, c2) in ccs]) has no duplicates\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"header(t2) is equal to header(t1) with all c1 \
         replaced with c2 for (c1, c2) in ccs\"),\n\
         (enforced=false, \"for all c in header(t2), if c == c2 for some (c1, \
         c2) in ccs, then schema(t2)[c] == schema(t1)[c1]\"),\n\
         (enforced=false, \"otherwise, schema(t2)[c] == schema(t1)[c]\"),\n\
         (enforced=false, \"nrows(t2) == nrows(t1)\")\n\
         ],\n\
         operation=let rename_columns =\n\
         fun (t1:[?], ccs:[(String,String)]) ->\n\
         let rename_map = ccs in\n\
         map(t1, fun r ->\n\
         to_lvs(r)\n\
         |> map(_, fun (label=l, value=v) ->\n\
         case  find_opt(rename_map, fun (from, _) -> from == l)\n\
         | Some((_, to)) => (label=to, value=v)\n\
         | None => (label=l, value=v) \n\
         end)\n\
         |> from_lvs) \n\
         in rename_columns,\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"find\",\n\
         requires=[\n\
         (enforced=false, \"for all c in header(r), c is in header(t)\"),\n\
         (enforced=false, \"for all c in header(r), schema(r)[c] == \
         schema(t)[c]\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"result is None or Some(n) where n in \
         range(nrows(t))\"),\n\
         (enforced=false, \"if Some(n), then getRow(t, n) matches r on all \
         fields in header(r)\")\n\
         ],\n\
         operation=let find =\n\
         fun (t:[?], r:?) ->\n\
         let is_match = fun (row:?) ->\n\
         let row_entries = to_lvs(row) in\n\
         let r_entries = to_lvs(r) in\n\
         all(r_entries, fun e ->\n\
         case  find_opt(row_entries, fun e' -> e'.label == e.label)\n\
         | Some(e') => e'.value == e.value\n\
         | None => false \n\
         end) \n\
         in\n\
         find_index(t, is_match) \n\
         in ?,\n\
         notes=[\"Returns an option type as opposed to an error\"]\n\
         ),\n\
         (\n\
         name=\"groupByRetentive\",\n\
         requires=[\n\
         (enforced=false, \"c is in header(t1)\"),\n\
         (enforced=false, \"schema(t1)[c] is a categorical sort\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"header(t2) == [key, groups]\"),\n\
         (enforced=false, \"schema(t2)[key] == schema(t1)[c]\"),\n\
         (enforced=false, \"schema(t2)[groups] == Table\"),\n\
         (enforced=false, \"getColumn(t2, key) has no duplicates\"),\n\
         (enforced=false, \"for all t in getColumn(t2, groups), schema(t) == \
         schema(t1)\"),\n\
         (enforced=false, \"nrows(t2) == length(removeDuplicates(getColumn(t1, \
         c)))\")\n\
         ],\n\
         operation=let get_value =\n\
         fun (r:?,label:String) ->\n\
         find_opt(to_lvs(r),fun e ->e.label ==label) |> option_map(_,fun e \
         ->e.value) \n\
         in\n\
         let remove_duplicates =\n\
         fun (xs:[?]) ->\n\
         fold_left(xs,\n\
         fun (seen,x) ->\n\
         if mem(seen,x) then seen else seen @ [x],\n\
         []) \n\
         in\n\
         let group_by_retentive =\n\
         fun (t1:[?],c:String) ->\n\
         let get_key =fun (r:?) ->get_value(r,c) in\n\n\
         let keys =\n\
         map(t1,get_key)\n\
         |>filter_map(_,fun opt ->opt)\n\
         |>remove_duplicates \n\
         in\n\n\
         map(keys,fun k ->\n\
         let rows =\n\
         filter(t1,fun r ->\n\
         case get_key(r)\n\
         |Some(k') =>k' ==k\n\
         |None =>false \n\
         end) \n\
         in\n\
         (key=k) ... (groups=rows)) \n\
         in,\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"groupBySubtractive\",\n\
         requires=[\n\
         (enforced=false, \"c is in header(t1)\"),\n\
         (enforced=false, \"schema(t1)[c] is a categorical sort\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"header(t2) == [key, groups]\"),\n\
         (enforced=false, \"schema(t2)[key] == schema(t1)[c]\"),\n\
         (enforced=false, \"schema(t2)[groups] == Table\"),\n\
         (enforced=false, \"getColumn(t2, key) has no duplicates\"),\n\
         (enforced=false, \"for all t in getColumn(t2, groups), header(t) == \
         removeAll(header(t1), [c])\"),\n\
         (enforced=false, \"for all t in getColumn(t2, groups), schema(t) is a \
         subsequence of schema(t1)\"),\n\
         (enforced=false, \"nrows(t2) == length(removeDuplicates(getColumn(t1, \
         c)))\")\n\
         ],\n\
         operation=                        \n\
         let groupBySubtractive = let get_value =\n\
         fun (r:?,label:String) ->\n\
         find_opt(to_lvs(r),fun e ->e.label ==label) |>option_map(_,fun e \
         ->e.value) \n\
         in\n\
         let remove_duplicates =\n\
         fun (xs:[?]) ->\n\
         fold_left(xs,\n\
         fun (seen,x) ->\n\
         if mem(seen,x) then seen else seen @[x],\n\
         []) \n\
         in\n\
         fun (t1:[?],c:String) ->\n\
         let get_key =fun (r:?) ->get_value(r,c) in\n\n\
         let keys =\n\
         map(t1,get_key)\n\
         |>filter_map(_,fun opt ->opt)\n\
         |>remove_duplicates \n\
         in\n\n\
         map(keys,fun k ->\n\
         let rows =\n\
         filter(t1,fun r ->\n\
         case get_key(r)\n\
         |Some(k') =>k' ==k\n\
         |None =>false \n\
         end)\n\
         |>map(_,fun r ->\n\
         to_lvs(r)\n\
         |>filter(_,fun e ->e.label!=c)\n\
         |>from_lvs) \n\
         in\n\
         (key=k) ...(groups=rows)) \n\
         in ?,\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"update\",\n\
         requires=[\n\
         (enforced=false, \"for all c in header(r2), c is in header(t1)\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"schema(r1) == schema(t1)\"),\n\
         (enforced=false, \"header(t2) == header(t1)\"),\n\
         (enforced=false, \"for all c in header(t2): if c in header(r2) then \
         schema(t2)[c] == schema(r2)[c]\"),\n\
         (enforced=false, \"otherwise, schema(t2)[c] == schema(t1)[c]\"),\n\
         (enforced=false, \"nrows(t2) == nrows(t1)\")\n\
         ],\n\
         operation=let update =\n\
         fun (t1: [?], f: (? -> ?)) ->\n\
         map(t1, fun r ->\n\
         let delta = f(r) in\n\
         let base = to_lvs(r) in\n\
         let updates = to_lvs(delta) in\n\
         let updated =\n\
         map(base, fun e ->\n\
         case find_opt(updates, fun u -> u.label == e.label)\n\
         | Some(u) => u\n\
         | None => e \n\
         end) \n\
         in\n\
         from_lvs(updated)) \n\
         in,\n\
         notes=[\"The idiomatic way to do this would be with map and ordinary \
         tuple extension\"]\n\
         )\n\n\
         ] in";
    } )
